void initialize_choose(int maxN, int P, ll choose[][501])
{
    for (int i = 0; i <= maxN; ++i)
    {
        choose[i][0] = 1;
        choose[i][i] = 1;
        for (int j = 1; j < i; ++j)
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % P;
    }
