int main(int argc, const char **argv)
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (argc > 1)
    {
        static std::filebuf f;
        f.open(argv[1], std::ios::in);
        cin.rdbuf(&f);
        if (!cin)
        {
            cerr << "Input file error\n";
            exit(1);
        }
    }
    if (argc > 2)
    {
        static std::filebuf f;
        f.open(argv[2], std::ios::out | std::ios::trunc);
        cout.rdbuf(&f);
        if (!cout)
        {
            cerr << "Output file error\n";
        }
    }
    int N, M, P;
    cin >> N >> M >> P;
    static ll choose[502][502];
    initialize_choose(N, P, choose);

    vector<ll> dp1(N + 1, 0);
    vector<ll> dpw(N + 1, 1);
    for (int m = 1; m <= M; ++m)
    {
        for (int i = 0; i < m; ++i)
