            ll s2 = (dp1[m - 1 - i] * dpw[i]) % P;
            ll add = ((s1 + s2) % P) * (m + 1) % P * choose[m - 1][i] % P;
            add = (add + w * (((ll)i * (i + 1) + (ll)(m - 1 - i) * (m - i)) / 2)) % P;
            (dp1[m] += add) %= P;
        }
    }

    static ll dp[502][502];
    static ll dps[502][502];
    memset(dp, 0, sizeof(dp));
    memset(dps, 0, sizeof(dps));
    dps[0][0] = 1;
    for (int i = 1; i <= N; ++i)
    {
        dp[i][i] = dp1[i];
        dps[i][i] = dpw[i];
        dps[i][0] = 1;
        for (int j = 1; j < i; ++j)
        {
            dp[i][j] = dp[i - 1][j];
            dps[i][j] = dps[i - 1][j];
            for (int k = 1; k <= j; ++k)
